1041: suite('smAgent: localAction arm_rework (gh-683 unresolved review threads)', function () {
1042: 
1043:     test('labels the PR agent:rework + explains in a comment; no workflow dispatched', function () {
1044:         // Live fa #1194/#1211/#1212 + dart #340 (2026-10-04): green +
1045:         // reviewed + validated machine PRs with OPEN review threads matched
1046:         // no rule (every re-review armer requires threadsResolved:true).
1047:         // arm_rework arms the PR label; rework-on-label (an existing rule)
1048:         // dispatches the leg and consumes the label — so this action must
1049:         // NOT dispatch anything itself.
1050:         var sm = makeSmAgent({
1051:             fileMap: { '../.dmtools/config.js': 'module.exports = { repository: { owner: "epam", repo: "dmtools-dart" } };' },
1052:             github: {
1053:                 items: [
1054:                     { key: 'pr-1211', labels: ['ai_pr_reviewed'], issueNumber: null, prNumber: 1211,
1055:                       pr: { number: 1211, state: 'OPEN', checks: 'green', mergeState: 'CLEAN', mergeable: true } }
1056:                 ]
1057:             }
1058:         });
1059: 
1060:         sm.action(baseParams('epam', 'dmtools-dart', [{
1061:             description: 'unresolved review threads on a machine-authored reviewed PR -> arm agent:rework',
1062:             source: 'github',
1063:             query: {
1064:                 type: 'pr',
1065:                 labels: ['ai_pr_reviewed'],
1066:                 notLabels: ['agent:rework', 'agent:review', 'ai_validating', 'pr_approved', 'validation_failed'],
1067:                 prMachineAuthor: true,
1068:                 threadsResolved: false,
1069:                 draft: false
1070:             },
1071:             localAction: 'arm_rework',
1072:             limit: 5,
1073:             id: 'rework-unresolved-threads'
1074:         }]));
1075: 
1076:         assert.equal(sm.capturedPrLabelAdds.length, 1, 'exactly one label write');
1077:         assert.equal(sm.capturedPrLabelAdds[0].number, 1211, 'the label lands on the PR');
1078:         assert.equal(sm.capturedPrLabelAdds[0].labels.join(','), 'agent:rework');
1079:         assert.equal(sm.capturedPrLabelAdds[0].workspace, 'epam', 'owner from rule context');
1080:         assert.equal(sm.capturedPrLabelAdds[0].repository, 'dmtools-dart', 'repo from rule context');
1081:         assert.equal(sm.capturedPrComments.length, 1, 'exactly one explanatory comment');
1082:         assert.contains(sm.capturedPrComments[0].body, 'Unresolved review threads',
1083:             'the comment states the reason (matches conflict_rework report style)');
1084:         assert.contains(sm.capturedPrComments[0].body, 'rework leg owns open threads',
1085:             'the comment states the owner-design mechanism');
1086:         assert.equal(sm.capturedTriggers.length, 0,
1087:             'no workflow dispatched — rework-on-label owns the dispatch (issue-anchored, PR-anchored fallback #544)');
1088:         assert.equal(sm.capturedCloses.length, 0, 'no issue churn');
1089:     });
1090: });
1091: 
1092: suite('smAgent: arm_rework red-gate max attempts (gh-917 first validation)', function () {
1093: 
1094:     // gh-917 (epam/dmtools-dart 2026-10-16): fresh dev PRs #413/#414 sat
1095:     // with red FIRST validations while the SM processed 0 — the red-gate
1096:     // rule required ai_pr_reviewed. The widened rule (any machine-authored
1097:     // red head, first validation included) arms via the SAME arm_rework
1098:     // action, gated by rule.redHeadGated: the arm records the SHARED 🔴
1099:     // red-head marker budget fail_validation writes, and at redHeadCap
1100:     // (default 3) recorded reds on the UNCHANGED head the arm is WITHHELD
1101:     // and the owner is escalated ONCE per head — no infinite retry on
1102:     // unfixable-without-toolchain violations.
1103: 
1104:     var RULE = {
1105:         description: 'red pre-merge gate on ANY machine-authored PR -> arm agent:rework (first validation included)',
1106:         source: 'github',
1107:         query: {
1108:             type: 'pr',
1109:             checks: ['red'],
1110:             notLabels: ['ai_validating', 'validation_failed', 'agent:rework', 'chore:pin'],
1111:             prMachineAuthor: true,
1112:             notMergeState: ['BEHIND', 'DIRTY'],
1113:             draft: false
1114:         },
1115:         localAction: 'arm_rework',
1116:         redHeadGated: true,
1117:         limit: 1,
1118:         id: 'rework-on-red-gate-unlatched'
1119:     };
1120: 
1121:     function devItem(n, head, extra) {
1122:         var it = { key: 'pr-' + n, labels: [], issueNumber: null, prNumber: n, draft: false,
1123:                    headSha: head };
1124:         if (extra) { for (var k in extra) { if (extra.hasOwnProperty(k)) it[k] = extra[k]; } }
1125:         return it;
1126:     }
1127: 
1128:     function config(owner, repo) {
1129:         return { fileMap: { '../.dmtools/config.js':
1130:             'module.exports = { repository: { owner: "' + owner + '", repo: "' + repo + '" } };' } };
1131:     }
1132: 
1133:     function markerComment(body) { return { body: body }; }
1134: 
1135:     var HEAD = 'a413a413a413a413a413a413a413a413a413a413';
1136: 
1137:     test('first red validation: arms agent:rework on the PR + records the shared red-head marker', function () {
1138:         var sm = makeSmAgent(Object.assign(config('epam', 'dmtools-dart'), {
1139:             github: {
1140:                 items: [devItem(413, HEAD, { pr: { number: 413, state: 'OPEN',
1141:                     checks: 'red', mergeState: 'BLOCKED', mergeable: false } })],
1142:                 pr: { number: 413, body: 'Closes #412', head: { sha: HEAD } },
1143:                 prComments: []
1144:             }
1145:         }));
1146:         sm.action({ jobParams: { owner: 'epam', repo: 'dmtools-dart',
1147:             machineAuthor: 'ai-teammate', rules: [RULE] } });
1148: 
1149:         assert.equal(sm.capturedPrLabelAdds.length, 1, 'the arm lands');
1150:         assert.equal(sm.capturedPrLabelAdds[0].number, 413, 'PR carrier (rework-on-label dispatches)');
1151:         assert.deepEqual(sm.capturedPrLabelAdds[0].labels, ['agent:rework']);
1152:         assert.equal(sm.capturedPrComments.length, 1, 'one explanatory comment');
1153:         var body = sm.capturedPrComments[0].body;
1154:         assert.contains(body, '\uD83D\uDD34 red head ' + HEAD + ' \u2014 red 1/3',
1155:             'the shared per-head budget is recorded with the SAME marker fail_validation writes');
1156:         assert.contains(body, 'gh-917', 'the comment names the coverage (first validation included)');
1157:         assert.equal(sm.capturedTriggers.length, 0, 'arm_rework never dispatches — rework-on-label owns it');
1158:     });
1159: 
1160:     test('second red on the same head: arms again and INCREMENTS the marker (red 2/3)', function () {
1161:         var sm = makeSmAgent(Object.assign(config('epam', 'dmtools-dart'), {
1162:             github: {
1163:                 items: [devItem(413, HEAD, { pr: { number: 413, state: 'OPEN',
1164:                     checks: 'red', mergeState: 'BLOCKED', mergeable: false } })],
1165:                 pr: { number: 413, body: 'Closes #412', head: { sha: HEAD } },
1166:                 prComments: [markerComment('\uD83D\uDD34 red head ' + HEAD +
1167:                     ' \u2014 red 1/3 (owner directive 2026-10-04: red yields the slot)')]
1168:             }
1169:         }));
1170:         sm.action({ jobParams: { owner: 'epam', repo: 'dmtools-dart',
1171:             machineAuthor: 'ai-teammate', rules: [RULE] } });
1172: 
1173:         assert.equal(sm.capturedPrLabelAdds.length, 1, 'below the cap the arm still fires');
1174:         assert.contains(sm.capturedPrComments[0].body,
1175:             '\uD83D\uDD34 red head ' + HEAD + ' \u2014 red 2/3',
1176:             'the recorded count increments toward the cap');
1177:     });
1178: 
1179:     test('at redHeadCap recorded reds on the unchanged head the arm is WITHHELD + owner escalated', function () {
1180:         var sm = makeSmAgent(Object.assign(config('epam', 'dmtools-dart'), {
1181:             github: {
1182:                 items: [devItem(413, HEAD, { pr: { number: 413, state: 'OPEN',
1183:                     checks: 'red', mergeState: 'BLOCKED', mergeable: false } })],
