1348: function shellQuote(s) {
1349:     return "'" + String(s).replace(/'/g, "'\\''") + "'";
1350: }
1351: 
1352: /**
1353:  * gh api PUT to Contents API with base64 content piped via stdin (`-F content=@-`
1354:  * + heredoc) so large state/history JSON payloads never hit Linux MAX_ARG_STRLEN
1355:  * (131,072B per execve argument, ~96.7KB of raw JSON when base64-expanded in argv).
1356:  */
1357: function contentsPutStdin(repo, path, branch, message, json, existingSha) {
1358:     var put = 'gh api -X PUT repos/' + repo + '/contents/' + path +
1359:         ' -f branch=' + branch +
1360:         ' -f message=' + shellQuote(message) +
1361:         ' -F content=@-';
1362:     if (existingSha) {
1363:         put += ' -f sha=' + shellQuote(existingSha);
1364:     }
1365:     return put + ' <<__FA_EOF__\n$(printf %s ' + shellQuote(json) +
1366:         ' | base64)\n__FA_EOF__';
1367: }
1368: 
1369: /**
1370:  * Time-travel history (owner 2026-09-24): every tick also lands a
1371:  * timestamped snapshot `<base>-<stamp>.json` (unique name → always a
1372:  * create, no sha) and rewrites the rolling index `<base>-history.json`
1373:  * the factory board probes for its scrub/play controls. The index keeps
1374:  * the newest `cfg.historyKeep` (default 500 = ~41h at 5-min / ~83h at 10-min)
1375:  * snapshots; snapshot URLs are absolute raw links the board fetches
1376:  * directly. Every command starts with `gh` (executor whitelist); the
1377:  * index body is decoded in-shell (`| base64 -d`), so the JS side never
1378:  * needs a base64 codec.
1379:  */
1380: function stampOf(state) {
1381:     var at = String((state && state.tick && state.tick.at) || '');
1382:     // '2026-09-23T22:35:55.658Z' → '20260923-2235' (pure string surgery)
1383:     return at.slice(0, 10).replace(/-/g, '') + '-' + at.slice(11, 16).replace(':', '');
1384: }
